// src/components/SpendingPriority.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority({ formData, updateData }) {
  const navigate = useNavigate();

  const [priorities, setPriorities] = useState({});

  // Initialize slider values if coming back from BudgetLimits
  useEffect(() => {
    if (formData && formData.spendingPriority) {
      setPriorities(formData.spendingPriority);
    } else if (formData && formData.category) {
      // Initialize all categories to 0
      const initialPriorities = {};
      formData.category.forEach((cat) => {
        initialPriorities[cat] = 0;
      });
      setPriorities(initialPriorities);
    }
  }, [formData]);

  const handleSliderChange = (category, value) => {
    setPriorities((prev) => ({
      ...prev,
      [category]: Number(value),
    }));
  };

  const handleNext = () => {
    // Ensure at least one category has priority >= 1
    if (!Object.values(priorities).some((v) => v > 0)) {
      alert("Please set priority for at least one category");
      return;
    }

    updateData({ spendingPriority: priorities });
    navigate("/budget"); // Go to BudgetLimits
  };

  if (!formData.category || formData.category.length === 0) {
    return <p style={{ textAlign: "center", color: "red" }}>No income categories selected</p>;
  }

  return (
    <div className="spending-container">
      <h2 className="spending-title">Set Your Spending Priorities</h2>
      <div className="spending-grid">
        {formData.category.map((cat) => (
          <div key={cat} className="spending-card">
            <h3 className="spending-name">{cat}</h3>
            <input
              type="range"
              min={0}
              max={5}
              value={priorities[cat] || 0}
              onChange={(e) => handleSliderChange(cat, e.target.value)}
              className="spending-slider"
            />
            <p>Priority: {priorities[cat] || 0}</p>
          </div>
        ))}
      </div>
      <button onClick={handleNext} className="next-button">
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
